import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

pad3d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void pad3d_kernel(const float* __restrict__ input,
                             float* __restrict__ output,
                             int N, int C,
                             int D_in, int H_in, int W_in,
                             int pad,
                             int D_out, int H_out, int W_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N*C*D_out*H_out*W_out;
    if (idx < total) {
        int w = idx % W_out;
        int tmp = idx / W_out;
        int h = tmp % H_out;
        tmp = tmp / H_out;
        int d = tmp % D_out;
        tmp = tmp / D_out;
        int c = tmp % C;
        int n = tmp / C;

        int in_d = d - pad;
        int in_h = h - pad;
        int in_w = w - pad;

        if (in_d >= 0 && in_d < D_in && in_h >= 0 && in_h < H_in && in_w >= 0 && in_w < W_in) {
            int input_idx = (((n*C + c)*D_in + in_d)*H_in + in_h)*W_in + in_w;
            output[idx] = input[input_idx];
        } else {
            output[idx] = 0.0f;
        }
    }
}

torch::Tensor pad3d_cuda(torch::Tensor input, int pad) {
    auto sizes = input.sizes();
    int N = sizes[0];
    int C = sizes[1];
    int D_in = sizes[2];
    int H_in = sizes[3];
    int W_in = sizes[4];
    int D_out = D_in + 2*pad;
    int H_out = H_in + 2*pad;
    int W_out = W_in + 2*pad;

    auto out = torch::zeros({N, C, D_out, H_out, W_out}, input.options());

    int total = N*C*D_out*H_out*W_out;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    pad3d_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(),
                                            out.data_ptr<float>(),
                                            N, C, D_in, H_in, W_in,
                                            pad,
                                            D_out, H_out, W_out);

    return out;
}
"""

pad3d_cpp_source = r"torch::Tensor pad3d_cuda(torch::Tensor input, int pad);"

pad3d = load_inline(
    name="pad3d",
    cpp_sources=pad3d_cpp_source,
    cuda_sources=pad3d_source,
    functions=["pad3d_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.pad = padding
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=0, output_padding=output_padding,
            groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x_padded = pad3d.pad3d_cuda(x, self.pad)
        return self.conv_transpose3d(x_padded)
